mapper.select:
SELECT a.id, a.doc_num AS 'docNum', a.bd_name AS 'bdName', a.hotb_id AS 'hotbId', a.hots_id AS 'hotsId', a.channel, a.country, c2.name AS 'countrys', a.invit_id AS 'invitId', b.doc_num AS 'invitDocNum', a.project_id AS 'projectId', c.name AS 'projectName', a.state, d.label AS 'states' FROM a_hot_coop a LEFT JOIN `a_hot_invit` b ON b.id = a.invit_id LEFT JOIN `a_project` c ON c.id = a.project_id LEFT JOIN `sys_dict` d ON d.value = a.state AND d.type = 'hot_state' AND d.del_flag = 0 LEFT JOIN `a_country` c2 ON c2.`id` = a.`country` JOIN `sys_user_country` uc ON uc.`country_id` = a.`country` WHERE a.`del_flag` = 0 AND uc.`user_id` = #{userid}
AND a.create_time >= #{sdate}
AND a.create_time <= #{edate}
AND a.`country` = #{country}
AND a.`bd_name` LIKE CONCAT('%',#{bdName},'%')
AND a.`state` = #{state}
AND a.`channel` = #{channel}
AND a.`hots_id` LIKE CONCAT('%',#{hotsId},'%')
AND c.name LIKE CONCAT('%',#{projectName},'%')
AND a.`id` IN
#{item}
ORDER BY id DESC

SELECT a.doc_num AS 'docNum', a.bd_name AS 'bdName', a.hots_id AS 'hotsId', a.channel, c2.name AS 'country', a1.doc_num AS 'invitDocNum', sd2.label AS 'state', p.name AS 'projectName', b.product_model AS 'productModel', b.product_color AS 'productColor', b.video_auth AS 'videoAuth', b.video_auth_pur AS 'videoAuthPur', b.ad_auth AS 'adAuth', b.coop_form AS 'coopForm', b.comm_rate AS 'commRate', b.pay_method AS 'payMethod', b.plat_form AS 'platForm', b.pay_info AS 'payInfo', b.pay_addres AS 'payAddres', b.coop_fee AS 'coopFee', b.sash_no AS 'sashNo', b.carrier AS 'carrier', b.sash_time AS 'sashTime', b.wl_status AS 'wlStatus', b.dh_date AS 'dhDate', b.utm_url AS 'utmUrl', b.sales_period AS 'salesPeriod', b.clicks AS 'clicks', b.sales AS 'sales', b.dis_code AS 'disCode', b.gmv AS 'gmv', b.roas AS 'roas', c.rele_chan AS 'dataReleChan', c.rele_acct AS 'dataReleAcct', c.amount AS 'dataAmount', c.apply_time AS 'dataApplyTime', c.pay_time AS 'dataPayTime', c.reles_date AS 'dataPayTime', c.vid_type AS 'dataVidType', c.vid_draft_url AS 'dataVidDraftUrl', c.mate_name AS 'dataMateName', c.pro_draft_time AS 'dataProDraftTime', c.rele_time AS 'dataReleTime', c.online_url AS 'dataOnlineUrl', c.ad_code AS 'dataAdCode', c.ad_code_expiry AS 'dataAdCodeExpiry', c.duration AS 'dataDuration', sd.label AS 'dataCreativ', c.score AS 'dataScore', c.score_level AS 'dataScoreLevel', c.views AS 'dataViews', c.likes AS 'dataLikes', c.comments AS 'dataComments', c.shares AS 'dataShares', c.favors AS 'dataFavors', c.rate_nox AS 'dataRateNox', c.dlj_clicks AS 'dataDljClicks', c.cpm AS 'dataCpm', c.cpc AS 'dataCpc', c.period AS 'dataPeriod', c.spend AS 'dataSpend', c.plays AS 'dataPlays', c.clicks AS 'dataClicks', c.conve AS 'dataConve', c.roas AS 'dataRoas', d.apply_time AS 'settApplyTime', d.pay_time AS 'settPayTime', d.pay_amount AS 'settPayAmount' FROM a_hot_coop a LEFT JOIN `a_hot_invit` a1 ON a1.id = a.invit_id LEFT JOIN `a_hot_coop_product` b ON b.`coop_id` = a.`id` AND b.`del_flag` = 0 LEFT JOIN `a_hot_coop_data` c ON c.`coop_id` = b.`id` AND c.`del_flag` = 0 LEFT JOIN `a_hot_coop_sett` d ON d.`coop_id` = b.`id` AND d.`del_flag` = 0 LEFT JOIN `a_project` p ON p.id = a.project_id LEFT JOIN `sys_dict` sd ON sd.value = c.creativ AND sd.type = 'b_creativ' AND sd.del_flag = 0 LEFT JOIN `sys_dict` sd2 ON sd2.`value` = a.`state` AND sd2.`type` = 'hot_state' AND sd2.`del_flag` = 0 LEFT JOIN `a_country` c2 ON c2.`id` = a.`country` JOIN `sys_user_country` uc ON uc.`country_id` = a.`country` WHERE a.del_flag = 0 AND uc.`user_id` = #{userid}
AND a.create_time >= #{sdate}
AND a.create_time <= #{edate}
AND a.`country` = #{country}
AND a.`bd_name` LIKE CONCAT('%',#{bdName},'%')
AND a.`state` = #{state}
AND a.`channel` = #{channel}
AND a.`hots_id` LIKE CONCAT('%',#{hotsId},'%')
AND c.name LIKE CONCAT('%',#{projectName},'%')
AND a.`id` IN
#{item}
ORDER BY a.id DESC

SELECT a.`id`, a.doc_num AS docNum, a.bd_name AS bdName, a.hots_id AS hotsId, a.channel, a.country, c2.name AS "countrys", a.state, d.`label` AS states, b.rele_chan AS releChan, b.rele_acct AS releAcct, b.vid_type AS vidType, b.vid_draft_url AS vidDraftUrl, b.online_url AS onlineUrl, b.views, b.likes, b.comments, b.shares, b.period, b.spend, b.plays, b.clicks AS dclicks, b.conve, b.roas AS droas, c.product_model AS productModel, c.product_color AS productColor, c.video_auth_pur AS videoAuthPur, c.coop_form AS coopForm, c.plat_form AS platForm, c.coop_fee AS coopFee, c.sash_no AS sashNo, c.carrier, c.wl_status AS wlStatus, c.utm_url AS utmUrl, c.sales_period AS salesPeriod, c.clicks, c.sales, c.gmv AS gmv, c.roas AS roas FROM `a_hot_coop` a LEFT JOIN `a_hot_coop_data` b ON b.`coop_id` = a.`id` AND b.`del_flag` = 0 LEFT JOIN `a_hot_coop_product` c ON c.`coop_id` = a.`id` AND c.`del_flag` = 0 LEFT JOIN `sys_dict` d ON d.`value` = a.`state` AND d.`type` = 'hot_state' AND d.`del_flag` = 0 LEFT JOIN `a_country` c2 ON c2.`id` = a.`country` JOIN `sys_user_country` uc ON uc.`country_id` = a.`country` WHERE a.`del_flag` = 0 AND uc.`user_id` = #{userid}
AND a.`country` = #{country}
AND a.`bd_name` LIKE CONCAT('%',#{bdName},'%')
AND a.`state` = #{state}
AND a.`channel` = #{channel}
AND a.`hots_id` LIKE CONCAT('%',#{hotsId},'%')

SELECT a.doc_num AS 'docNum', a.bd_name AS 'bdName', a.hots_id AS 'hotsId', a.channel, c2.name AS 'country', a1.doc_num AS 'invitDocNum', sd2.label AS 'state', p.name AS 'projectName', b.product_model AS 'productModel', b.product_color AS 'productColor', b.video_auth AS 'videoAuth', b.video_auth_pur AS 'videoAuthPur', b.ad_auth AS 'adAuth', b.coop_form AS 'coopForm', b.comm_rate AS 'commRate', b.pay_method AS 'payMethod', b.plat_form AS 'platForm', b.pay_info AS 'payInfo', b.pay_addres AS 'payAddres', b.coop_fee AS 'coopFee', b.sash_no AS 'sashNo', b.carrier AS 'carrier', b.sash_time AS 'sashTime', b.wl_status AS 'wlStatus', b.dh_date AS 'dhDate', b.utm_url AS 'utmUrl', b.sales_period AS 'salesPeriod', b.clicks AS 'clicks', b.sales AS 'sales', b.dis_code AS 'disCode', b.gmv AS 'gmv', b.roas AS 'roas', c.rele_chan AS 'dataReleChan', c.rele_acct AS 'dataReleAcct', c.amount AS 'dataAmount', c.apply_time AS 'dataApplyTime', c.pay_time AS 'dataPayTime', c.reles_date AS 'dataPayTime', c.vid_type AS 'dataVidType', c.vid_draft_url AS 'dataVidDraftUrl', c.mate_name AS 'dataMateName', c.pro_draft_time AS 'dataProDraftTime', c.rele_time AS 'dataReleTime', c.online_url AS 'dataOnlineUrl', c.ad_code AS 'dataAdCode', c.ad_code_expiry AS 'dataAdCodeExpiry', c.duration AS 'dataDuration', sd.label AS 'dataCreativ', c.score AS 'dataScore', c.score_level AS 'dataScoreLevel', c.views AS 'dataViews', c.likes AS 'dataLikes', c.comments AS 'dataComments', c.shares AS 'dataShares', c.favors AS 'dataFavors', c.rate_nox AS 'dataRateNox', c.dlj_clicks AS 'dataDljClicks', c.cpm AS 'dataCpm', c.cpc AS 'dataCpc', c.period AS 'dataPeriod', c.spend AS 'dataSpend', c.plays AS 'dataPlays', c.clicks AS 'dataClicks', c.conve AS 'dataConve', c.roas AS 'dataRoas', d.apply_time AS 'settApplyTime', d.pay_time AS 'settPayTime', d.pay_amount AS 'settPayAmount' FROM a_hot_coop a LEFT JOIN `a_hot_invit` a1 ON a1.id = a.invit_id LEFT JOIN `a_hot_coop_product` b ON b.`coop_id` = a.`id` AND b.`del_flag` = 0 LEFT JOIN `a_hot_coop_data` c ON c.`coop_id` = b.`id` AND c.`del_flag` = 0 LEFT JOIN `a_hot_coop_sett` d ON d.`coop_id` = b.`id` AND d.`del_flag` = 0 LEFT JOIN `a_project` p ON p.id = a.project_id LEFT JOIN `sys_dict` sd ON sd.value = c.creativ AND sd.type = 'b_creativ' AND sd.del_flag = 0 LEFT JOIN `sys_dict` sd2 ON sd2.`value` = a.`state` AND sd2.`type` = 'hot_state' AND sd2.`del_flag` = 0 LEFT JOIN `a_country` c2 ON c2.`id` = a.`country` JOIN `sys_user_country` uc ON uc.`country_id` = a.`country` WHERE a.`del_flag` = 0 AND uc.`user_id` = #{userid}
AND a.`country` = #{country}
AND a.`bd_name` LIKE CONCAT('%',#{bdName},'%')
AND a.`state` = #{state}
AND a.`channel` = #{channel}
AND a.`hots_id` LIKE CONCAT('%',#{hotsId},'%')

SELECT GROUP_CONCAT(b.doc_num) AS 'msg' FROM ( SELECT a.id, SUM(IF(LENGTH(IFNULL(c.creativ, ''))=0,1,0)) AS 'num' FROM `a_hot_coop` a JOIN `a_hot_coop_product` b ON b.coop_id = a.id AND b.del_flag = 0 JOIN `a_hot_coop_data` c ON c.coop_id = b.id AND c.del_flag = 0 WHERE a.del_flag = 0 AND a.id IN
#{item}
GROUP BY a.id ) a JOIN `a_hot_coop` b ON b.id = a.id WHERE a.num > 0
